class Sim {
  constructor(seed) {
    this.reset(seed);
  }

  reset(seed) {
    const s = seed === undefined || seed === null || seed === "" ? 1 : (seed | 0);
    this.seed = s;
    this.rng = mulberry32(s);
    this.t = 0;
    this.acc = 0;
    this.started = false;
    this.paused = false;
    this.demo = false;
    this.outcome = null;
    this.phase = 1;
    this.phaseShiftUntil = 0;
    this.nextSpawnAt = INTRO;
    this.novaUsed = false;
    this.attackSeq = 0;
    this.attacks = [];
    this.events = [];
    this.pressLog = [];
    this.combo = 0;
    this.bestCombo = 0;
    this.score = 0;
    this.tempers = 0;
    this.perfects = 0;
    this.whiffs = 0;
    this.hits = 0;
    this.player = {
      hp: PLAYER_MAX,
      maxHp: PLAYER_MAX,
      x: 0,
      y: 228,
      temperUntil: 0,
      recoverUntil: 0,
      invulnUntil: 0,
      bufferUntil: -1,
      lastPress: -9999
    };
    this.boss = {
      name: BOSS_NAME,
      hp: BOSS_MAX,
      maxHp: BOSS_MAX,
      staggerUntil: 0
    };
    return this.snapshot();
  }

  start() {
    if (this.outcome) return this.snapshot();
    this.started = true;
    this.paused = false;
    return this.snapshot();
  }

  setDemo(enabled) {
    this.demo = !!enabled;
    if (this.demo) {
      if (this.outcome) this.reset(this.seed);
      this.demo = true;
      this.started = true;
      this.paused = false;
    }
    return this.snapshot();
  }

  press() {
    if (!this.started && !this.outcome) {
      this.start();
      return this.snapshot();
    }
    if (!this.started || this.paused || this.outcome) return this.snapshot();
    const p = this.player;
    if (this.t < p.recoverUntil) {
      p.bufferUntil = this.t + BUFFER;
      return this.snapshot();
    }
    this._temper();
    return this.snapshot();
  }

  _temper() {
    const p = this.player;
    p.lastPress = this.t;
    p.temperUntil = this.t + ACTIVE;
    p.recoverUntil = this.t + ACTIVE + RECOVER;
    p.bufferUntil = -1;
    this.tempers += 1;
    this.pressLog.push(this.t);
    this.events.push({ type: "temper", t: this.t, x: p.x, y: p.y });

    let hit = null;
    let best = 1e9;
    for (let i = 0; i < this.attacks.length; i++) {
      const a = this.attacks[i];
      if (a.resolved) continue;
      if (this.t < a.windowStart - 40 || this.t > a.windowEnd + 20) continue;
      const dist = Math.abs(this.t - a.impactTime);
      if (dist < best) {
        best = dist;
        hit = a;
      }
    }
    if (!hit) {
      this.whiffs += 1;
      this.combo = 0;
      return;
    }
    this._parry(hit);
  }

  _parry(a) {
    a.resolved = true;
    a.parried = true;
    const perfect = this.t >= a.impactTime - 48 && this.t <= a.impactTime + 28;
    a.perfect = perfect;
    this.combo += 1;
    if (this.combo > this.bestCombo) this.bestCombo = this.combo;
    this.score += (perfect ? 180 : 110) + this.combo * 12;
    if (perfect) this.perfects += 1;
    this.boss.hp = Math.max(0, this.boss.hp - BOSS_DMG[a.kind]);
    this.boss.staggerUntil = this.t + (perfect ? 180 : 110);
    this.events.push({
      type: "parry",
      t: this.t,
      kind: a.kind,
      perfect: perfect,
      x: this.player.x,
      y: this.player.y,
      phase: this.phase
    });
    this._checkPhase();
    if (this.boss.hp <= 0) this._end("success");
  }

  _checkPhase() {
    const next = this.boss.hp <= PHASE3_HP ? 3 : this.boss.hp <= PHASE2_HP ? 2 : 1;
    if (next > this.phase) {
      this.phase = next;
      this.phaseShiftUntil = this.t + PHASE_SHIFT;
      this.nextSpawnAt = this.phaseShiftUntil + 200;
      for (let i = 0; i < this.attacks.length; i++) {
        const a = this.attacks[i];
        if (!a.resolved) {
          a.resolved = true;
          a.fizzled = true;
        }
      }
      this.events.push({ type: "phase", t: this.t, phase: this.phase });
    }
  }

  _end(outcome) {
    this.outcome = outcome;
    this.events.push({ type: outcome, t: this.t });
  }

  _pickKind() {
    const r = this.rng();
    if (this.phase === 1) return r < 0.72 ? "lance" : "drip";
    if (this.phase === 2) {
      if (r < 0.38) return "ribbon";
      if (r < 0.78) return "double";
      return "lance";
    }
    if (!this.novaUsed && this.boss.hp <= 28) {
      this.novaUsed = true;
      return "nova";
    }
    return r < 0.7 ? "ring" : "lance";
  }

  _pushAttack(kind, delay) {
    const tel = TELEGRAPH[kind];
    const impactTime = this.t + delay + tel;
    const id = ++this.attackSeq;
    const side = this.rng() < 0.5 ? -1 : 1;
    this.attacks.push({
      id: id,
      kind: kind,
      spawnTime: this.t + delay,
      telegraphStart: this.t + delay,
      impactTime: impactTime,
      windowStart: impactTime - EARLY[kind],
      windowEnd: impactTime + LATE[kind],
      resolved: false,
      parried: false,
      perfect: false,
      fizzled: false,
      side: side,
      dripX: this.player.x + (this.rng() - 0.5) * 36
    });
  }

  _spawn() {
    if (this.t < this.nextSpawnAt || this.t < this.phaseShiftUntil) return;
    const kind = this._pickKind();
    if (kind === "double") {
      this._pushAttack("lance", 0);
      this._pushAttack("lance", 480);
      this.nextSpawnAt = this.t + GAP.double + Math.floor(this.rng() * 180);
    } else {
      this._pushAttack(kind, 0);
      this.nextSpawnAt = this.t + GAP[kind] + Math.floor(this.rng() * 160);
    }
  }

  _demoThink() {
    if (!this.demo || this.paused || this.outcome) return;
    if (this.t < this.player.recoverUntil) return;
    for (let i = 0; i < this.attacks.length; i++) {
      const a = this.attacks[i];
      if (a.resolved) continue;
      const pressAt = a.impactTime - 40;
      if (this.t >= pressAt && this.t < pressAt + DT) {
        this._temper();
        return;
      }
    }
  }

  _resolve() {
    const p = this.player;
    for (let i = 0; i < this.attacks.length; i++) {
      const a = this.attacks[i];
      if (a.resolved) continue;
      if (this.t < a.impactTime) continue;
      a.resolved = true;
      a.parried = false;
      if (p.invulnUntil > this.t) continue;
      p.hp -= 1;
      p.invulnUntil = this.t + INVULN;
      this.combo = 0;
      this.hits += 1;
      this.events.push({ type: "hit", t: this.t, kind: a.kind, x: p.x, y: p.y });
      if (p.hp <= 0) {
        p.hp = 0;
        this._end("failure");
        return;
      }
    }
  }

  tick() {
    if (this.outcome) return;
    if (this.player.bufferUntil >= 0 && this.t >= this.player.recoverUntil && this.t <= this.player.bufferUntil) {
      this._temper();
    }
    if (this.outcome) return;
    this._demoThink();
    if (this.outcome) return;
    this.t += DT;
    this._spawn();
    this._resolve();
  }

  step(milliseconds) {
    const ms = Number(milliseconds);
    if (!Number.isFinite(ms) || ms <= 0) return this.snapshot();
    if (this.paused || !this.started || this.outcome) return this.snapshot();
    this.acc += ms;
    let guard = 0;
    while (this.acc >= DT && guard++ < 12000) {
      this.acc -= DT;
      this.tick();
      if (this.paused || this.outcome) {
        this.acc = 0;
        break;
      }
    }
    return this.snapshot();
  }

  snapshot() {
    const p = this.player;
    const active = [];
    for (let i = 0; i < this.attacks.length; i++) {
      const a = this.attacks[i];
      if (a.resolved || this.t < a.telegraphStart) continue;
      active.push({
        id: a.id,
        kind: a.kind,
        impactIn: r3(a.impactTime - this.t),
        windowStart: a.windowStart,
        windowEnd: a.windowEnd
      });
    }
    return {
      simulationTime: this.t,
      phase: this.phase,
      started: this.started,
      paused: this.paused,
      demo: this.demo,
      seed: this.seed,
      outcome: this.outcome,
      player: {
        hp: p.hp,
        maxHp: p.maxHp,
        x: r3(p.x),
        y: r3(p.y),
        tempering: this.t < p.temperUntil,
        invuln: this.t < p.invulnUntil,
        recoverMs: Math.max(0, p.recoverUntil - this.t)
      },
      boss: {
        name: this.boss.name,
        hp: this.boss.hp,
        maxHp: this.boss.maxHp,
        staggering: this.t < this.boss.staggerUntil
      },
      attacks: active,
      score: {
        value: this.score,
        combo: this.combo,
        bestCombo: this.bestCombo,
        tempers: this.tempers,
        perfects: this.perfects,
        whiffs: this.whiffs,
        hits: this.hits
      }
    };
  }
}

function runSelfTest() {
  const tests = [];
  const check = (name, fn) => {
    try {
      const detail = fn();
      tests.push({ name: name, passed: true, detail: detail || "ok" });
    } catch (err) {
      tests.push({ name: name, passed: false, detail: String(err && err.message ? err.message : err) });
    }
  };

  const runDemo = (seed, maxMs) => {
    const s = new Sim(seed);
    s.setDemo(true);
    const phases = new Set([s.phase]);
    for (let t = 0; t < maxMs && !s.outcome; t += DT) {
      s.step(DT);
      phases.add(s.phase);
      s.events.length = 0;
    }
    return { sim: s, phases: phases };
  };

  const demo = runDemo(4242, 100000);

  check("deterministic reset", () => {
    const a = new Sim(1234);
    a.setDemo(true);
    a.step(30000);
    a.events.length = 0;
    const b = new Sim(999);
    b.step(5000);
    b.reset(1234);
    b.setDemo(true);
    b.step(30000);
    b.events.length = 0;
    if (JSON.stringify(a.snapshot()) !== JSON.stringify(b.snapshot())) {
      throw new Error("same seed + same inputs diverged");
    }
    return "identical snapshots after 30 s";
  });

  check("pause behavior", () => {
    const s = new Sim(7);
    s.start();
    s.step(3000);
    const t0 = s.t;
    s.paused = true;
    s.step(2000);
    if (s.t !== t0) throw new Error("time advanced while paused");
    s.paused = false;
    s.step(160);
    if (s.t <= t0) throw new Error("time did not resume");
    return "frozen while paused, resumes after";
  });

  check("phase progression", () => {
    if (!demo.phases.has(2) || !demo.phases.has(3)) {
      throw new Error("phases seen: " + Array.from(demo.phases).join(","));
    }
    return "phases 1 → 2 → 3 reached";
  });

  check("finite numeric state", () => {
    const bad = [];
    const walk = (o, p) => {
      if (typeof o === "number") {
        if (!Number.isFinite(o)) bad.push(p);
      } else if (Array.isArray(o)) {
        o.forEach((v, i) => walk(v, p + "[" + i + "]"));
      } else if (o && typeof o === "object") {
        for (const k in o) walk(o[k], p + "." + k);
      }
    };
    walk(demo.sim.snapshot(), "win");
    const mid = new Sim(11);
    mid.setDemo(true);
    mid.step(20000);
    walk(mid.snapshot(), "mid");
    if (bad.length) throw new Error("non-finite at " + bad.join(", "));
    return "all snapshot numbers finite";
  });

  check("reachable success state", () => {
    if (demo.sim.outcome !== "success") throw new Error("demo outcome: " + demo.sim.outcome);
    if (demo.sim.t < 40000 || demo.sim.t > 80000) throw new Error("duration " + demo.sim.t);
    return "success at " + (demo.sim.t / 1000).toFixed(1) + " s";
  });

  check("reachable failure state", () => {
    const s = new Sim(4242);
    s.start();
    for (let t = 0; t < 60000 && !s.outcome; t += DT) {
      s.step(DT);
      s.events.length = 0;
    }
    if (s.outcome !== "failure") throw new Error("no-input outcome: " + s.outcome);
    return "failure at " + (s.t / 1000).toFixed(1) + " s without input";
  });

  check("restart", () => {
    const fresh = new Sim(9);
    const s = new Sim(9);
    s.setDemo(true);
    s.step(25000);
    s.events.length = 0;
    s.reset(9);
    if (JSON.stringify(s.snapshot()) !== JSON.stringify(fresh.snapshot())) {
      throw new Error("reset state differs from fresh state");
    }
    s.start();
    fresh.start();
    s.step(4000);
    fresh.step(4000);
    if (JSON.stringify(s.snapshot()) !== JSON.stringify(fresh.snapshot())) {
      throw new Error("post-reset evolution differs");
    }
    return "reset ≡ fresh encounter";
  });

  check("demo uses the normal gameplay state", () => {
    const d = demo.sim;
    if (d.tempers < 8) throw new Error("demo barely interacted: " + d.tempers + " tempers");
    const log = d.pressLog.slice();
    const r = new Sim(4242);
    r.start();
    let i = 0;
    while (!r.outcome && r.t < d.t + 1000) {
      while (i < log.length && log[i] < r.t) i++;
      if (i < log.length && log[i] === r.t) {
        r.press();
        i++;
      }
      r.step(DT);
      r.events.length = 0;
    }
    const a = d.snapshot();
    const b = r.snapshot();
    a.demo = false;
    b.demo = false;
    if (JSON.stringify(a) !== JSON.stringify(b)) {
      throw new Error("manual replay of demo inputs diverged");
    }
    return "demo inputs replayed manually → identical result (" + d.tempers + " tempers)";
  });

  return { passed: tests.every((t) => t.passed), tests: tests };
}

const live = new Sim(1);
const canvas = document.getElementById("arena");
const ctx = canvas.getContext("2d");
const ui = {
  start: document.getElementById("btn-start"),
  pause: document.getElementById("btn-pause"),
  restart: document.getElementById("btn-restart"),
  demo: document.getElementById("btn-demo"),
  mute: document.getElementById("btn-mute"),
  bossName: document.getElementById("boss-name"),
  bossHp: document.getElementById("boss-hp"),
  bossFill: document.getElementById("boss-fill"),
  playerHp: document.getElementById("player-hp"),
  playerFill: document.getElementById("player-fill"),
  phase: document.getElementById("phase-label"),
  pips: [
    document.getElementById("pip-1"),
    document.getElementById("pip-2"),
    document.getElementById("pip-3")
  ],
  instruction: document.getElementById("instruction"),
  banner: document.getElementById("banner"),
  bannerTitle: document.getElementById("banner-title"),
  bannerBody: document.getElementById("banner-body"),
  combo: document.getElementById("combo")

