+  </div>
+<script>
+"use strict";
+
+var DT = 20;
+var RECOVER = 240;
+var EARLY = 150;
+var LATE = 110;
+var PERFECT = 60;
+var LEAD = 40;
+var INTRO = 2800;
+var P1_GAP = 3200;
+var P1_TEL = 1200;
+var P1_FIRST = 1600;
+var P1_DMG = 6;
+var P2_GAP = 3800;
+var P2_TEL = 1000;
+var P2_ECHO = 800;
+var P2_DMG = 4;
+var P2_SHIFT = 1800;
+var P3_GAP = 3200;
+var P3_TEL = 1000;
+var P3_DMG = 3;
+var P3_BREAK = 12;
+var P3_SHIFT = 2000;
+var PHASE2_HP = 64;
+var PHASE3_HP = 32;
+var BOSS_MAX = 100;
+var PLAYER_MAX = 5;
+var INVULN = 860;
+var OMEGA = Math.PI * 2 / 7400;
+var ANGLE0 = -Math.PI / 2;
+var BOSS_NAME = "Vell, the Kiln Saint";
