+var CAPTION = [
+  "",
+  "",
+  "A true ring carries you across.",
+  "Every third ring breaks the heart."
+];
+
+function mulberry32(seed) {
+  var a = seed | 0;
+  return function () {
+    a = (a + 0x6d2b79f5) | 0;
+    var t = Math.imul(a ^ (a >>> 15), 1 | a);
+    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+  };
