+  this.acc = 0;
+  this.started = false;
+  this.paused = false;
+  this.demo = false;
+  this.outcome = null;
+  this.phase = 1;
+  this.phaseShiftUntil = 0;
+  this.nextSpawnAt = INTRO;
+  this.attackSeq = 0;
+  this.pairSeq = 0;
+  this.p1Spawns = 0;
+  this.attacks = [];
+  this.events = [];
+  this.pressLog = [];
+  this.particles = [];
+  this.combo = 0;
+  this.bestCombo = 0;
+  this.score = 0;
+  this.parries = 0;
+  this.perfects = 0;
+  this.whiffs = 0;
+  this.hits = 0;
+  this.vaults = 0;
+  this.resonance = 0;
+  this.heartBreaks = 0;
+  this.lastBreakT = -9999;
+  this.vaultOffset = 0;
+  this.juiceT = -9999;
+  this.juicePower = 0;
+  this.juiceKind = "";
+  this.juiceAngle = ANGLE0;
+  this.cracks = [];
+  var i;
+  for (i = 0; i < 8; i++) {
+    this.cracks.push({
+      a: this.rng(),
+      b: this.rng(),
+      c: this.rng()
+    });
+  }
+  this.player = {
+    hp: PLAYER_MAX,
+    maxHp: PLAYER_MAX,
+    lastPress: -9999,
+    recoverUntil: 0,
+    invulnUntil: 0
+  };
+  this.boss = {
+    name: BOSS_NAME,
+    hp: BOSS_MAX,
+    maxHp: BOSS_MAX,
+    staggerUntil: 0
+  };
