+    this.demo = true;
+    this.started = true;
+    this.paused = false;
+  }
+  return this.snapshot();
+};
+
+Sim.prototype.press = function () {
+  if (!this.started || this.paused || this.outcome) return this.snapshot();
+  if (this.t < this.player.recoverUntil) return this.snapshot();
