+  return this.snapshot();
+};
+
+Sim.prototype._spark = function (angle, n, color) {
+  var i;
+  for (i = 0; i < n; i++) {
+    if (this.particles.length > 90) this.particles.shift();
+    var a = this.visRng() * Math.PI * 2;
+    var sp = 0.25 + this.visRng() * 0.9;
+    var life = 260 + this.visRng() * 220;
