+    this._end("success");
+    return;
+  }
+  this._checkPhase();
+};
+
+Sim.prototype._checkPhase = function () {
+  var next = this.phase;
+  if (this.phase === 1 && this.boss.hp <= PHASE2_HP) next = 2;
+  else if (this.phase === 2 && this.boss.hp <= PHASE3_HP) next = 3;
