+  this.nextSpawnAt = this.phaseShiftUntil + 400;
+  var i;
+  for (i = 0; i < this.attacks.length; i++) {
+    var a = this.attacks[i];
+    if (!a.resolved) {
+      a.resolved = true;
+      a.fizzled = true;
+      a.resolvedAt = this.t;
+      a.finish = "fizzle";
+    }
+  }
+  this.juiceT = this.t;
+  this.juicePower = 10;
+  this.juiceKind = "phase";
+  this.events.push({ type: "phase", t: this.t, phase: next });
+};
+
+Sim.prototype._end = function (outcome) {
+  this.outcome = outcome;
+  var i;
+  for (i = 0; i < this.attacks.length; i++) {
+    var a = this.attacks[i];
+    if (!a.resolved) {
+      a.resolved = true;
+      a.fizzled = true;
+      a.resolvedAt = this.t;
+      a.finish = "fizzle";
+    }
+  }
+  this.events.push({ type: outcome, t: this.t });
+};
+
+Sim.prototype._push = function (kind, telegraph, opt) {
+  var impactTime = this.t + telegraph;
+  var aimExtra = opt.aimExtra || 0;
+  var aim = this.angleAt(impactTime, this.vaultOffset + aimExtra);
+  var atk = {
+    id: ++this.attackSeq,
+    kind: kind,
+    role: opt.role,
+    pairId: opt.pairId || 0,
+    spawnTime: this.t,
+    impactTime: impactTime,
+    windowStart: impactTime - EARLY,
+    windowEnd: impactTime + LATE,
+    aim: aim,
+    armed: opt.role !== "echo",
+    resolved: false,
+    parried: false,
+    perfect: false,
+    fizzled: false,
+    resolvedAt: 0,
+    finish: "",
+    flourish: this.rng(),
+    demoDone: false
