+  this._ring();
+};
+
+Sim.prototype._resolve = function () {
+  var i;
+  for (i = 0; i < this.attacks.length; i++) {
+    if (this.outcome) return;
+    var a = this.attacks[i];
+    if (a.resolved || this.t <= a.windowEnd) continue;
+    if (!a.armed) {
+      a.resolved = true;
+      a.fizzled = true;
+      a.resolvedAt = this.t;
+      a.finish = "fizzle";
+      continue;
+    }
+    a.resolved = true;
+    a.resolvedAt = this.t;
+    a.finish = "hurt";
