+    this.resonance = 0;
+    this.hits += 1;
+    this.juiceT = this.t;
+    this.juicePower = 9;
+    this.juiceKind = "hurt";
+    this.juiceAngle = a.aim;
+    this._spark(a.aim, 8, "#9d2430");
