+      return;
+    }
+  }
+};
+
+Sim.prototype._trail = function () {
+  this.trail.push(this.playerAngle());
+  if (this.trail.length > 14) this.trail.shift();
+};
+
+Sim.prototype._particles = function () {
+  var i;
+  if (this.t > 0 && this.t % 400 === 0) {
+    var ang = this.visRng() * Math.PI * 2;
+    this.particles.push({
+      x: Math.cos(ang) * (0.15 + this.visRng() * 0.45),
+      y: Math.sin(ang) * 0.1 + 0.25,
+      vx: (this.visRng() - 0.5) * 0.05,
+      vy: -0.18 - this.visRng() * 0.12,
+      life: 700,
+      max: 700,
+      rot: 0,
+      spin: 0,
+      w: 1.4,
+      color: "#e06a32"
