+  }
+  for (i = this.particles.length - 1; i >= 0; i--) {
+    var p = this.particles[i];
+    p.life -= DT;
+    if (p.life <= 0) {
+      this.particles.splice(i, 1);
+      continue;
+    }
+    p.x += p.vx * DT * 0.0016;
+    p.y += p.vy * DT * 0.0016;
