+    p.rot += p.spin * DT;
+  }
+};
+
+Sim.prototype.tick = function () {
+  if (this.outcome) return;
+  this._demoThink();
+  if (this.outcome) return;
+  this.t += DT;
+  this._spawn();
+  this._resolve();
+  this._trail();
+  this._particles();
+};
+
+Sim.prototype.step = function (milliseconds) {
+  var ms = Number(milliseconds);
+  if (!Number.isFinite(ms) || ms <= 0) return this.snapshot();
+  if (this.paused || !this.started || this.outcome) return this.snapshot();
+  this.acc += ms;
+  var guard = 0;
+  while (this.acc >= DT && guard++ < 20000) {
+    this.acc -= DT;
+    this.tick();
+    if (this.paused || this.outcome) {
+      this.acc = 0;
+      break;
+    }
+  }
+  return this.snapshot();
+};
+
+Sim.prototype.snapshot = function () {
+  var ang = this.playerAngle();
+  var active = [];
+  var i;
+  for (i = 0; i < this.attacks.length; i++) {
+    var a = this.attacks[i];
+    if (a.resolved || this.t < a.spawnTime) continue;
+    active.push({
+      id: a.id,
+      kind: a.kind,
+      role: a.role,
+      impactIn: r3(a.impactTime - this.t),
+      armed: a.armed
+    });
+  }
+  return {
+    simulationTime: this.t,
+    phase: this.phase,
+    started: this.started,
+    paused: this.paused,
+    demo: this.demo,
+    seed: this.seed,
+    outcome: this.outcome,
+    player: {
+      hp: this.player.hp,
+      maxHp: this.player.maxHp,
+      angle: r3(ang),
+      x: r3(Math.cos(ang)),
+      y: r3(Math.sin(ang)),
+      swinging: this.t - this.player.lastPress >= 0 && this.t - this.player.lastPress < 260,
+      invulnerable: this.t < this.player.invulnUntil,
+      resonance: this.resonance,
+      vaults: this.vaults
+    },
+    boss: {
+      name: this.boss.name,
+      hp: this.boss.hp,
+      maxHp: this.boss.maxHp,
+      staggering: this.t < this.boss.staggerUntil,
+      heartBreaks: this.heartBreaks
+    },
+    attacks: active,
+    score: {
+      value: this.score,
+      combo: this.combo,
+      bestCombo: this.bestCombo,
+      parries: this.parries,
+      perfects: this.perfects,
+      whiffs: this.whiffs,
+      hits: this.hits
+    }
+  };
+};
+
+function runSelfTest() {
+  var tests = [];
+  function check(name, fn) {
+    try {
+      var detail = fn();
+      tests.push({ name: name, passed: true, detail: detail || "ok" });
+    } catch (err) {
+      tests.push({
+        name: name,
+        passed: false,
+        detail: String(err && err.message ? err.message : err)
+      });
+    }
+  }
+  function runDemo(seed, maxMs) {
+    var s = new Sim(seed);
+    s.setDemo(true);
