+    } else if (o && typeof o === "object") {
+      for (var k in o) finiteWalk(o[k], path + "." + k, bad);
+    }
+  }
+
+  var demo = runDemo(4242, 100000);
+
+  check("deterministic reset", function () {
+    var a = new Sim(1234);
+    a.setDemo(true);
+    a.step(30000);
+    var b = new Sim(999);
+    b.step(5000);
+    b.reset(1234);
+    b.setDemo(true);
+    b.step(30000);
