+  });
+
+  check("pause behavior", function () {
+    var s = new Sim(7);
+    s.start();
+    s.step(3000);
+    var t0 = s.t;
+    var hp = s.boss.hp;
+    s.paused = true;
+    s.press();
+    s.step(2000);
+    if (s.t !== t0) throw new Error("time advanced while paused");
+    if (s.boss.hp !== hp) throw new Error("state changed while paused");
+    s.paused = false;
+    s.step(200);
+    if (s.t <= t0) throw new Error("time did not resume");
+    return "frozen while paused, resumes after";
+  });
