+  }
+  ctx.strokeStyle = "#1a0c10";
+  ctx.lineWidth = 1.6;
+  ctx.beginPath();
+  ctx.arc(-6 * sc, -88 * sc, 7 * sc, 0.15 * Math.PI, 0.85 * Math.PI);
+  ctx.stroke();
+  ctx.beginPath();
+  ctx.moveTo(-2 * sc, -62 * sc);
+  ctx.quadraticCurveTo(8 * sc, -56 * sc, 16 * sc, -64 * sc);
+  ctx.stroke();
+
+  var crown;
+  ctx.fillStyle = "#2a1214";
+  for (crown = 0; crown < 5; crown++) {
+    var hx = (-18 + crown * 12) * sc;
+    var hh = (16 + (live.cracks[crown].b * 18) + (crown === 3 ? 10 : 0)) * sc;
+    ctx.beginPath();
+    ctx.moveTo(hx, -112 * sc);
+    ctx.lineTo(hx + 5 * sc, -112 * sc - hh);
+    ctx.lineTo(hx + 11 * sc, -112 * sc);
+    ctx.fill();
+  }
+
+  ctx.strokeStyle = "rgba(231,179,74,0.45)";
+  ctx.lineWidth = 1.3;
+  var chain;
+  for (chain = 0; chain < 3; chain++) {
+    var cx0 = (34 + chain * 8) * sc;
+    ctx.beginPath();
+    ctx.moveTo(cx0, -8 * sc);
+    ctx.lineTo(cx0 + 2 * sc, 54 * sc);
+    ctx.stroke();
+    ctx.beginPath();
+    ctx.arc(cx0 + 2 * sc, 58 * sc, 2.4 * sc, 0, Math.PI * 2);
+    ctx.stroke();
+  }
+
+  ctx.restore();
+
+  ctx.save();
+  ctx.translate(cx + recoil, cy + bob);
+  var tip = ringXY(0, 0, R, aim, R * (0.55 + telegraph * 0.25));
+  ctx.strokeStyle = telegraph > 0.72 ? "#f6f1e6" : "#6e1a26";
+  ctx.lineWidth = 12 * Math.max(0.8, sc / 1.4);
+  ctx.lineCap = "round";
+  ctx.beginPath();
+  ctx.moveTo(-8 * sc, -70 * sc);
+  ctx.bezierCurveTo(-70 * sc, -40 * sc, tip[0] * 0.45, tip[1] * 0.45 - 20 * sc, tip[0] * 0.78, tip[1] * 0.78);
+  ctx.stroke();
+  ctx.strokeStyle = "rgba(231,179,74,0.85)";
+  ctx.lineWidth = 3 * Math.max(0.8, sc / 1.6);
+  ctx.beginPath();
+  ctx.moveTo(-14 * sc, -78 * sc);
+  ctx.bezierCurveTo(-78 * sc, -58 * sc, tip[0] * 0.5, tip[1] * 0.4 - 40 * sc, tip[0] * 0.7, tip[1] * 0.62);
+  ctx.stroke();
+  ctx.beginPath();
+  ctx.moveTo(-48 * sc, -96 * sc);
+  ctx.quadraticCurveTo(-70 * sc, -120 * sc, -36 * sc, -108 * sc);
+  ctx.stroke();
+  ctx.restore();
+}
+
+function attackProgress(a) {
+  var span = Math.max(1, a.impactTime - a.spawnTime);
+  return Math.max(0, Math.min(1, (live.t - a.spawnTime) / span));
+}
+
+function drawSeal(x, y, s, hot, flourish, alpha) {
+  ctx.save();
+  ctx.translate(x, y);
+  ctx.rotate(flourish * 0.6);
+  ctx.globalAlpha = alpha;
+  ctx.beginPath();
+  ctx.moveTo(0, -s);
+  ctx.lineTo(s * 0.72, 0);
+  ctx.lineTo(0, s);
+  ctx.lineTo(-s * 0.72, 0);
+  ctx.closePath();
+  ctx.fillStyle = hot ? "rgba(255,244,220,0.9)" : "rgba(231,179,74,0.14)";
+  ctx.strokeStyle = hot ? "#fff6e4" : "#e7b34a";
+  ctx.lineWidth = hot ? 2.5 : 1.6;
+  ctx.fill();
+  ctx.stroke();
+  ctx.beginPath();
+  ctx.moveTo(0, -s * 0.45);
+  ctx.lineTo(s * 0.28, 0);
+  ctx.lineTo(0, s * 0.45);
+  ctx.stroke();
+  ctx.restore();
+}
+
+function drawAttacks(cx, cy, R) {
+  var i;
+  var byPair = {};
+  for (i = 0; i < live.attacks.length; i++) {
+    var a = live.attacks[i];
+    if (!a.pairId) continue;
+    if (!byPair[a.pairId]) byPair[a.pairId] = {};
+    byPair[a.pairId][a.role] = a;
+  }
+  for (var key in byPair) {
+    var pair = byPair[key];
+    if (!pair.primary || !pair.echo) continue;
+    if (pair.primary.resolved && pair.echo.resolved) continue;
+    var p1 = ringXY(cx, cy, R, pair.primary.aim);
+    var p2 = ringXY(cx, cy, R, pair.echo.aim);
+    ctx.beginPath();
+    ctx.moveTo(p1[0], p1[1]);
+    ctx.lineTo(p2[0], p2[1]);
+    ctx.strokeStyle = pair.echo.armed ? "rgba(143,217,207,0.9)" : "rgba(143,217,207,0.35)";
+    ctx.lineWidth = 2;
+    ctx.setLineDash([5, 7]);
+    ctx.stroke();
+    ctx.setLineDash([]);
+  }
+
+  for (i = 0; i < live.attacks.length; i++) {
+    var atk = live.attacks[i];
+    var age = atk.resolved ? live.t - atk.resolvedAt : 0;
+    if (atk.resolved && (age > 260 || age < 0)) continue;
+    var prog = atk.resolved ? 1 : attackProgress(atk);
+    var hot = prog > 0.72;
+    var pos = ringXY(cx, cy, R, atk.aim);
+    var alpha = atk.resolved ? Math.max(0, 1 - age / 260) : atk.armed ? 1 : 0.45;
+    var s = Math.max(12, R * 0.075) * (0.82 + prog * 0.35);
+
+    if (!atk.resolved && atk.kind !== "iris") {
+      var from = [cx, cy - R * 0.05];
+      var spark = [
+        from[0] + (pos[0] - from[0]) * prog,
+        from[1] + (pos[1] - from[1]) * prog
+      ];
+      ctx.beginPath();
+      ctx.moveTo(from[0], from[1]);
+      ctx.lineTo(spark[0], spark[1]);
+      ctx.strokeStyle = hot ? "rgba(255,246,228,0.8)" : "rgba(224,106,50,0.55)";
+      ctx.lineWidth = 2;
+      ctx.stroke();
+      ctx.fillStyle = hot ? "#fff6e4" : "#e06a32";
+      ctx.beginPath();
+      ctx.arc(spark[0], spark[1], hot ? 4.5 : 3, 0, Math.PI * 2);
+      ctx.fill();
+    }
+
+    ctx.save();
+    ctx.globalAlpha = alpha;
+    if (atk.kind === "spit") {
+      ctx.translate(pos[0], pos[1]);
+      ctx.fillStyle = hot ? "#fff6e4" : "#e06a32";
+      ctx.beginPath();
+      ctx.moveTo(0, -s);
+      ctx.quadraticCurveTo(s * 0.7, 0, 0, s * 0.8);
+      ctx.quadraticCurveTo(-s * 0.7, 0, 0, -s);
+      ctx.fill();
+    } else if (atk.kind === "antler") {
+      ctx.strokeStyle = hot ? "#fff6e4" : "#9d2430";
+      ctx.lineWidth = hot ? 8 : 5;
+      ctx.beginPath();
+      ctx.arc(cx, cy, R, atk.aim - 0.34 * prog, atk.aim + 0.34 * prog);
+      ctx.stroke();
+      drawSeal(pos[0], pos[1], s * 0.7, hot, atk.flourish, 1);
+    } else if (atk.kind === "iris") {
+      ctx.translate(pos[0], pos[1]);
+      var blades = 6;
+      var k;
+      ctx.strokeStyle = hot ? "#fff6e4" : "#ff5a2a";
+      ctx.lineWidth = 2;
+      for (k = 0; k < blades; k++) {
+        ctx.beginPath();
+        ctx.rotate(Math.PI / 3);
+        ctx.arc(0, 0, s, 0.2 + (1 - prog) * 0.8, 0.9);
+        ctx.stroke();
+      }
+      ctx.beginPath();
+      ctx.arc(0, 0, Math.max(2, s * (1 - prog * 0.75)), 0, Math.PI * 2);
+      ctx.stroke();
+    } else if (atk.kind === "lance") {
+      ctx.strokeStyle = hot ? "#fff6e4" : "#ff5a2a";
+      ctx.lineWidth = 1 + prog * 4;
+      ctx.beginPath();
+      ctx.moveTo(cx, cy);
+      ctx.lineTo(pos[0], pos[1]);
+      ctx.stroke();
+      drawSeal(pos[0], pos[1], s, hot, atk.flourish, 1);
+    } else {
+      drawSeal(pos[0], pos[1], s, hot, atk.flourish, 1);
+    }
+    if (hot && !atk.resolved) {
+      ctx.beginPath();
+      ctx.arc(pos[0], pos[1], s * 1.35, 0, Math.PI * 2);
+      ctx.strokeStyle = "rgba(255,246,228,0.7)";
+      ctx.lineWidth = 1.25;
+      ctx.stroke();
+    }
+    ctx.restore();
+  }
+}
+
+function drawPlayer(cx, cy, R) {
+  var ang = live.playerAngle();
+  var pos = ringXY(cx, cy, R, ang);
+  var pr = Math.max(11, R * 0.07);
+  var age = live.t - live.player.lastPress;
+  var swing = -0.55;
+  if (age >= 0 && age < 280) {
+    var u = age / 280;
+    if (u < 0.2) swing = -0.55 - u * 1.4;
+    else if (u < 0.48) swing = -0.83 + ((u - 0.2) / 0.28) * 2.1;
+    else swing = 1.27 - ((u - 0.48) / 0.52) * 1.82;
+  }
+  var inv = live.t < live.player.invulnUntil;
+  if (!(inv && Math.floor(live.t / 80) % 2 === 0)) {
+    if (!reduce && live.trail.length > 1) {
+      ctx.beginPath();
+      var ti;
+      for (ti = 0; ti < live.trail.length; ti++) {
+        var tp = ringXY(cx, cy, R, live.trail[ti]);
+        if (ti === 0) ctx.moveTo(tp[0], tp[1]);
+        else ctx.lineTo(tp[0], tp[1]);
+      }
+      ctx.strokeStyle = "rgba(143,217,207,0.45)";
+      ctx.lineWidth = 3;
+      ctx.stroke();
+    }
+    ctx.save();
+    ctx.translate(pos[0], pos[1]);
+    var squash = 1;
+    var stretch = 1;
+    if (!reduce && age >= 40 && age < 120) {
+      squash = 1.18;
+      stretch = 0.84;
+    }
+    ctx.rotate(ang + Math.PI / 2);
+    ctx.scale(squash, stretch);
+    ctx.fillStyle = "#143f3c";
+    ctx.beginPath();
+    ctx.ellipse(0, 4, pr * 0.72, pr * 0.95, 0, 0, Math.PI * 2);
+    ctx.fill();
+    ctx.fillStyle = "#e7f7f4";
+    ctx.beginPath();
+    ctx.arc(0, -pr * 0.15, pr * 0.62, 0, Math.PI * 2);
+    ctx.fill();
+    ctx.strokeStyle = "#8fd9cf";
+    ctx.lineWidth = 2;
+    ctx.stroke();
+    ctx.strokeStyle = "#e7b34a";
+    ctx.lineWidth = Math.max(3, pr * 0.22);
+    ctx.beginPath();
+    ctx.moveTo(0, 0);
+    ctx.lineTo(Math.cos(swing) * pr * 2.15, Math.sin(swing) * pr * 2.15);
+    ctx.stroke();
+    ctx.fillStyle = "#f6f1e6";
+    ctx.beginPath();
+    ctx.arc(Math.cos(swing) * pr * 2.15, Math.sin(swing) * pr * 2.15, pr * 0.38, 0, Math.PI * 2);
+    ctx.fill();
+    ctx.strokeStyle = "#e7b34a";
+    ctx.stroke();
+    ctx.restore();
+  }
+}
+
+function drawParticles(cx, cy, R) {
+  if (reduce) return;
+  var i;
+  for (i = 0; i < live.particles.length; i++) {
+    var p = live.particles[i];
+    var x = cx + p.x * R;
+    var y = cy + p.y * R * 0.9;
+    var alpha = Math.max(0, p.life / p.max);
+    ctx.save();
+    ctx.translate(x, y);
+    ctx.rotate(p.rot);
+    ctx.globalAlpha = alpha;
+    ctx.fillStyle = p.color;
+    ctx.fillRect(-p.w, -p.w * 0.35, p.w * 2, p.w * 0.7);
+    ctx.restore();
+  }
+}
+
+function drawJuice(cx, cy, R) {
+  if (reduce) return;
+  var age = live.t - live.juiceT;
+  if (age < 0 || age > 420) return;
+  var pos = ringXY(cx, cy, R, live.juiceAngle);
+  var k = age / 420;
+  ctx.beginPath();
+  ctx.arc(pos[0], pos[1], 8 + k * R * 0.28, 0, Math.PI * 2);
+  ctx.strokeStyle = live.juiceKind === "hurt" ? "rgba(157,36,48," + (1 - k) + ")" : "rgba(246,241,230," + (1 - k) + ")";
+  ctx.lineWidth = 2;
+  ctx.stroke();
+  if (age < 90 && live.juiceKind !== "hurt") {
+    ctx.fillStyle = "rgba(255,246,228," + (0.16 * (1 - age / 90)) + ")";
+    ctx.fillRect(0, 0, view.w, view.h);
+  }
+}
+
+function render() {
+  var w = view.w;
+  var h = view.h;
+  var cx = w * 0.5;
+  var cy = h * 0.52;
+  var R = Math.min(w, h) * 0.32;
+  if (R < 70) R = Math.min(70, Math.min(w, h) * 0.46);
+  buildGrain();
+  var shakeX = 0;
+  var shakeY = 0;
+  if (!reduce) {
+    var age = live.t - live.juiceT;
+    if (age >= 0 && age < 340) {
+      var mag = live.juicePower * (1 - age / 340) * (1 - age / 340);
+      shakeX = Math.sin(age * 0.48) * mag;
+      shakeY = Math.cos(age * 0.41) * mag * 0.6;
+    }
+  }
+  ctx.setTransform(canvas.width / w, 0, 0, canvas.height / h, 0, 0);
+  ctx.clearRect(0, 0, w, h);
+  ctx.save();
+  ctx.translate(shakeX, shakeY);
+  drawKiln(cx, cy, R);
+  drawVell(cx, cy, R);
+  drawAttacks(cx, cy, R);
+  drawPlayer(cx, cy, R);
+  drawParticles(cx, cy, R);
+  drawJuice(cx, cy, R);
+  if (grainCanvas) {
+    ctx.globalAlpha = 0.85;
+    ctx.drawImage(grainCanvas, 0, 0, w, h);
+    ctx.globalAlpha = 1;
+  }
+  var vig = ctx.createRadialGradient(cx, cy, R * 0.7, cx, cy, Math.max(w, h) * 0.7);
+  vig.addColorStop(0, "rgba(0,0,0,0)");
+  vig.addColorStop(1, "rgba(0,0,0,0.45)");
+  ctx.fillStyle = vig;
+  ctx.fillRect(0, 0, w, h);
+  ctx.restore();
+}
+
+function syncUI() {
+  var snap = live.snapshot();
+  ui.phase.textContent = live.started ? PHASE_NAME[snap.phase] : "The kiln is shut";
+  var pct = snap.boss.maxHp ? (snap.boss.hp / snap.boss.maxHp) * 100 : 0;
+  ui.bossFill.style.width = pct + "%";
+  ui.bossMeter.setAttribute("aria-valuenow", String(snap.boss.hp));
+  ui.bossHp.textContent = String(snap.boss.hp);
+  var pipNodes = ui.pips.querySelectorAll("span");
+  var n;
+  for (n = 0; n < pipNodes.length; n++) {
+    pipNodes[n].className = n < snap.player.hp ? "on" : "";
+  }
+  ui.pips.setAttribute("aria-valuenow", String(snap.player.hp));
+  ui.pips.setAttribute("aria-label", "Striker stability " + snap.player.hp + " of " + snap.player.maxHp);
+  ui.score.textContent = String(snap.score.value);
+  ui.combo.textContent = snap.score.combo > 1 ? snap.score.combo + " chain" : "";
+  ui.caption.textContent = live.started && !live.outcome ? CAPTION[snap.phase] : "";
+  if (snap.phase === 3 && live.started && !live.outcome) {
+    ui.heart.hidden = false;
+    var breaking = live.t - live.lastBreakT >= 0 && live.t - live.lastBreakT < 320;
+    var shown = breaking ? 3 : snap.player.resonance;
+    var marks = ui.heart.querySelectorAll("i");
+    for (n = 0; n < marks.length; n++) marks[n].className = n < shown ? "on" : "";
+  } else {
+    ui.heart.hidden = true;
+  }
+  ui.pause.textContent = live.paused ? "Resume" : "Pause";
+  ui.pause.setAttribute("aria-pressed", live.paused ? "true" : "false");
+  ui.demo.setAttribute("aria-pressed", live.demo ? "true" : "false");
+  ui.mute.setAttribute("aria-pressed", muted ? "true" : "false");
+  if (snap.outcome && focusedOutcome !== snap.outcome) {
+    focusedOutcome = snap.outcome;
+    if (snap.outcome === "success") {
+      ui.bannerKicker.textContent = "Cooled";
+      ui.bannerTitle.textContent = "The saint goes quiet";
+      ui.bannerBody.textContent = "Score " + snap.score.value + " · chain " + snap.score.bestCombo;
+    } else {
+      ui.bannerKicker.textContent = "Scorched";
+      ui.bannerTitle.textContent = "The kiln keeps you";
+      ui.bannerBody.textContent = "Restart and ring cleaner.";
+    }
+    ui.banner.hidden = false;
+    ui.restart.focus();
+  } else if (!snap.outcome) {
+    focusedOutcome = null;
+    ui.banner.hidden = true;
+  }
+  syncAudio();
+}
+
+function onAction() {
+  unlockAudio();
+  if (!live.started) {
+    live.start();
+    return;
+  }
+  if (live.outcome || live.paused) return;
+  live.press();
+}
+
+ui.start.addEventListener("click", function () {
+  unlockAudio();
+  if (live.outcome) return;
+  live.paused = false;
+  live.start();
+});
+ui.pause.addEventListener("click", function () {
+  if (!live.started || live.outcome) return;
+  live.paused = !live.paused;
+});
+ui.restart.addEventListener("click", function () {
+  var demoOn = live.demo;
+  var seed = live.seed;
+  audioCursor = 0;
+  live.reset(seed);
+  focusedOutcome = null;
+  if (demoOn) live.setDemo(true);
+  else live.start();
+});
+ui.demo.addEventListener("click", function () {
+  unlockAudio();
+  if (live.demo) {
+    live.setDemo(false);
+    return;
+  }
+  audioCursor = 0;
+  live.setDemo(true);
+});
+ui.mute.addEventListener("click", function () {
+  muted = !muted;
+  if (!muted) unlockAudio();
+});
+
+window.addEventListener("keydown", function (e) {
+  if (e.repeat) return;
+  if (e.code !== "Space") return;
+  var ae = document.activeElement;
+  if (ae && ae.closest && ae.closest("button")) return;
+  e.preventDefault();
+  onAction();
+});
+
+canvas.addEventListener("pointerdown", function (e) {
+  if (e.pointerType === "mouse" && e.button !== 0) return;
+  e.preventDefault();
+  onAction();
+});
+
+document.addEventListener("visibilitychange", function () {
+  lastFrame = performance.now();
+});
+
+window.addEventListener("resize", resize);
+if (window.ResizeObserver) {
+  var ro = new ResizeObserver(resize);
+  ro.observe(stage);
+}
+resize();
+
+function frame(now) {
+  requestAnimationFrame(frame);
+  var d = now - lastFrame;
+  lastFrame = now;
+  if (d < 0) d = 0;
+  if (d > 100) d = 100;
+  if (!live.paused && !document.hidden) visualT += d;
+  if (!document.hidden && live.started && !live.paused && !live.outcome) live.step(d);
+  render();
+  syncUI();
+}
+lastFrame = performance.now();
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>

